/* Shader modules wrap PvkShaderCode structs generated by tools/shaderc. */
#include <stdlib.h>

#include "pvk_internal.h"

PvkResult pvkCreateShaderModule(PvkDevice device, const PvkShaderModuleCreateInfo *info, PvkShaderModule *module)
{
    PvkShaderModule mod;
    const PvkShaderCode *code = info->code;

    (void)device;

    if (!code) {
        pvk_error("pvkCreateShaderModule: no shader code\n");
        return PVK_ERROR_INVALID_SHADER;
    }
    if (code->stage == PVK_SHADER_STAGE_VERTEX &&
        (!code->vu1CodeStart || code->vu1CodeEnd <= code->vu1CodeStart)) {
        pvk_error("vertex shader '%s' has no VU1 code\n", code->name);
        return PVK_ERROR_INVALID_SHADER;
    }

    mod = calloc(1, sizeof(struct PvkShaderModule_T));
    if (!mod)
        return PVK_ERROR_OUT_OF_HOST_MEMORY;
    mod->code = code;

    *module = mod;
    return PVK_SUCCESS;
}

void pvkDestroyShaderModule(PvkDevice device, PvkShaderModule module)
{
    (void)device;
    free(module);
}
